package com.kaipai.service.ai.profileimport; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.util.Base64;
public class ProfileImportCandidateProofService { private final String secret; public ProfileImportCandidateProofService(String secret){this.secret=secret;} public String issue(String requestId,String candidateId,String value,String sourceType,boolean requiresConfirmation){return sign(canonical(requestId,candidateId,value,sourceType,requiresConfirmation));} public boolean verify(String proof,String requestId,String candidateId,String value,String sourceType,boolean requiresConfirmation){return sign(canonical(requestId,candidateId,value,sourceType,requiresConfirmation)).equals(proof);} private String canonical(String a,String b,String c,String e,boolean d){return a+"|"+b+"|"+c+"|"+e+"|"+d;} private String sign(String value){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
